def _create_attempt_items(qid_type, score_type, compact):
    """compact=True — yangi tartib (bigint, int, int, int, smallint, smallint, jsonb); False — avvalgi tartib."""
    attempt = sa.Column('attempt_id', sa.BigInteger(), nullable=False)
    position = sa.Column('position', sa.SmallInteger(), nullable=False)
    qid = sa.Column('question_id', qid_type, nullable=False)
    version = sa.Column('question_version', sa.Integer(), nullable=False)
    answer = sa.Column('answer', sa.dialects.postgresql.JSONB(astext_type=sa.Text()), nullable=True)
    score = sa.Column('score', score_type, nullable=True)
    time_ms = sa.Column('time_ms', sa.Integer(), nullable=True)
    cols = [attempt, qid, version, time_ms, position, score, answer] if compact else \
           [attempt, position, qid, version, answer, score, time_ms]
    extra = [sa.CheckConstraint('score IS NULL OR score BETWEEN 0 AND 100', name=op.f('ck_attempt_items_score_range'))] \
        if compact else []
    op.create_table('attempt_items', *cols, *extra,
        sa.ForeignKeyConstraint(['attempt_id'], ['test_attempts.id'], name=op.f('fk_attempt_items_attempt_id_test_attempts'), ondelete='CASCADE'),
        sa.ForeignKeyConstraint(['question_id', 'question_version'], ['question_versions.question_id', 'question_versions.version'], name='fk_attempt_items_question_version'),
        sa.PrimaryKeyConstraint('attempt_id', 'position', name=op.f('pk_attempt_items'))
    )
